  constructor() {
    this.platform.backButton.subscribeWithPriority(10, (processNextHandler) => {
      if (!this.goBack()) {
        void processNextHandler();
      }
    });
    window.history.pushState({ celnova: true }, '', window.location.href);
    window.addEventListener('popstate', this.handlePopState);
    this.themeMode = (localStorage.getItem('themeMode') as ThemeMode | null) ?? 'system';
    this.systemDark = this.themeMediaQuery.matches;
    this.themeMediaQuery.addEventListener('change', this.handleSystemThemeChange);
    this.applyTheme();
    this.cartItems = this.products.slice(0, 3).map((product, index) => ({ product, quantity: index === 0 ? 1 : 2 }));
    this.updateCartCount();
    this.fotoPerfilUrl = this.photoService.fotoPerfilUrl;
    this.fotosPerfil = [...this.photoService.fotosPerfil];
  }

  get themeLabel(): string {
    if (this.themeMode === 'light') {
      return 'Tema claro';
    }

    if (this.themeMode === 'dark') {
      return 'Tema oscuro';
    }

    return 'Tema del sistema';
  }

  get filteredProducts(): Product[] {
    const term = this.searchTerm.trim().toLowerCase();
    if (!term) {
      return this.products;
    }

    return this.products.filter((product) => `${product.name} ${product.category}`.toLowerCase().includes(term));
  }

  get filteredCatalogProducts(): Product[] {
    const term = this.searchTerm.trim().toLowerCase();
    const candidates = [...this.products, this.launchProduct];

    return candidates.filter((product) => {
      const matchesCategory = product.category === this.selectedCategory;
      const matchesSearch = !term || `${product.name} ${product.category}`.toLowerCase().includes(term);
      return matchesCategory && matchesSearch;
    });
  }

  get filteredCatalogCategories(): CatalogCategory[] {
    const term = this.searchTerm.trim().toLowerCase();
    if (!term) {
      return this.catalogCategories;
    }

    return this.catalogCategories.filter((category) =>
      `${category.name} ${category.description}`.toLowerCase().includes(term),
    );
  }

  selectCategory(category: string): void {
    this.selectedCategory = category;
    this.navigateTo('category');
  }

  toggleFavorite(product: Product): void {
    product.favorite = !product.favorite;
  }

  openProductDetail(product: Product): void {
    this.selectedProduct = product;
    this.selectedColor = product.colors?.[0] ?? null;
    this.selectedStorage =
      product.storageOptions?.find((option) => option.price === product.price) ?? product.storageOptions?.[0] ?? null;
    this.navigateTo('detail');
    this.profileMenuOpen = false;
  }

  selectColor(color: ProductColor): void {
    this.selectedColor = color;
  }

  selectStorage(option: StorageOption): void {
    this.selectedStorage = option;
  }

  addToCart(_product: Product): void {
    const item = this.cartItems.find((cartItem) => cartItem.product.name === _product.name);
    if (item) {
      item.quantity += 1;
    } else {
      this.cartItems.push({ product: _product, quantity: 1 });
    }
    this.updateCartCount();
  }

  updateCartCount(): void {
    this.cartCount = this.cartItems.reduce((total, item) => total + item.quantity, 0);
  }

  changeQuantity(item: CartItem, change: number): void {
    item.quantity = Math.max(1, item.quantity + change);
    this.updateCartCount();
  }

  removeFromCart(item: CartItem): void {
    this.cartItems = this.cartItems.filter((cartItem) => cartItem !== item);
    this.updateCartCount();
  }

  get favoriteProducts(): Product[] {
    return this.products.filter((product) => product.favorite);
  }

  get selectedPrice(): string {
    return this.selectedStorage?.price ?? this.selectedProduct?.price ?? '';
  }

  get cartSubtotal(): number {
    return this.cartItems.reduce((total, item) => total + this.priceToNumber(item.product.price) * item.quantity, 0);
  }

  get cartDiscount(): number {
    return this.couponApplied ? Math.round(this.cartSubtotal * 0.1) : 0;
  }

  get cartShipping(): number {
    return this.cartSubtotal >= 120000 ? 0 : 20000;
  }

  get cartTax(): number {
    return Math.round((this.cartSubtotal - this.cartDiscount) * 0.19);
  }

  get amountToFreeShipping(): number {
    return Math.max(0, 120000 - this.cartSubtotal);
  }

  get shippingProgress(): number {
    return Math.min(100, Math.round((this.cartSubtotal / 120000) * 100));
  }

  get cartTotal(): number {
    return this.cartSubtotal - this.cartDiscount + this.cartShipping + this.cartTax;
  }

  formatCurrency(value: number): string {
    return `$${value.toLocaleString('es-CO')}`;
  }

  priceToNumber(value: string): number {
    return Number(value.replace(/[^\d]/g, ''));
  }

  applyCoupon(): void {
    const code = this.couponCode.trim().toLowerCase();

    if (code === 'oferton10') {
      this.couponApplied = true;
      this.couponError = '';
      return;
    }

    this.couponApplied = false;
    this.couponError = 'CupÃ³n no válido.';
  }

