  goToCheckoutPayment(): void {
    if (!this.checkoutAddressLine.trim() || !this.checkoutLocality.trim() || !this.checkoutPhone.trim()) {
      this.checkoutError = 'Completa la dirección, la localidad y el teléfono para continuar.';
      return;
    }
    if (!new RegExp('^' + this.colombianMobilePattern + '$').test(this.checkoutPhone.replace(/\s/g, ''))) {
      this.checkoutError = 'Ingresa un número de celular colombiano válido.';
      return;
    }
    this.checkoutError = '';
    this.openCheckoutPayment();
  }

  payCheckout(): void {
    if (this.checkoutPaymentMethod === 'card') {
      const cardNumber = this.checkoutCardNumber.replace(/\s/g, '');
      if (cardNumber.length < 15 || !this.checkoutCardHolder.trim() || this.checkoutCardCvv.trim().length < 3) {
        this.checkoutError = 'Revisa los datos de la tarjeta para continuar.';
        return;
      }
      if (!/^\d{2}\/\d{2}$/.test(this.checkoutCardExpiry.trim())) {
        this.checkoutError = 'El vencimiento debe tener el formato MM/AA.';
        return;
      }
    }
    this.checkoutError = '';
    this.openCheckoutConfirmation();
  }

  get checkoutPaymentLabel(): string {
    switch (this.checkoutPaymentMethod) {
      case 'pse':
        return 'Bancolombia PSE';
      case 'wallet':
        return 'Nequi / Daviplata';
      case 'wompi':
        return 'Wompi';
      default:
        return 'Tarjeta terminada en 4092';
    }
  }

  downloadCheckoutReceipt(): void {
    const lines = [
      'CELNOVA - Comprobante de transacción',
      '-------------------------------------',
      'Orden: #CN-90458',
      'CUS / Referencia: CUS-88392019482',
      'Estado: Transacción aprobada',
      'Total pagado: $1.714.400 COP',
      'Método de pago: ' + this.checkoutPaymentLabel,
      'Fecha: Hoy, 03:42 PM',
      'Factura electrónica DIAN: #FE-4895',
      '',
      'Gracias por comprar en Celnova.',
    ];
    const blob = new Blob([lines.join('\n')], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'comprobante-celnova-CN-90458.txt';
    link.click();
    URL.revokeObjectURL(url);
  }

