  saveProfileEdit(event: SubmitEvent): void {
    event.preventDefault();
    const username = this.editUsername.trim();
    const fullName = this.editFullName.trim();
    const profileEmail = this.editProfileEmail.trim().toLowerCase();
    const secondaryEmail = this.editSecondaryEmail.trim().toLowerCase();

    if (!username || !fullName) {
      this.profileEditError = 'El usuario y el nombre completo son obligatorios.';
      return;
    }

    if (!EMAIL_PATTERN.test(profileEmail)) {
      this.profileEditError = 'Ingresa un correo principal válido.';
      return;
    }

    if (secondaryEmail && !EMAIL_PATTERN.test(secondaryEmail)) {
      this.profileEditError = 'Ingresa un correo secundario válido.';
      return;
    }

    this.username = username;
    this.fullName = fullName;
    this.profileEmail = profileEmail;
    this.secondaryEmail = secondaryEmail;
    this.address = this.editAddress.trim();
    this.profileEditError = '';
    this.goBack();
  }

