  normalizePhone(event: Event): void {
    const input = event.target as HTMLInputElement;
    const digits = input.value.replace(/\D/g, '').slice(0, 10);
    input.value = digits;
    this.recoveryPhone = digits;
  }

  updateRegisterPhone(event: Event): void {
    const input = event.target as HTMLInputElement;
    const digits = input.value.replace(/\D/g, '').slice(0, 10);
    input.value = digits;
    this.registerPhone = digits;
  }

  getPhoneStatus(phone: string): 'valid' | 'length' | 'invalid' | '' {
    if (!phone) {
      return '';
    }

    if (phone.length < 10) {
      return 'length';
    }

    return COLOMBIAN_MOBILE_PATTERN.test(phone) ? 'valid' : 'invalid';
  }

  get phoneStatus(): 'valid' | 'length' | 'invalid' | '' {
    return this.getPhoneStatus(this.registerPhone);
  }

  get recoveryPhoneStatus(): 'valid' | 'length' | 'invalid' | '' {
    return this.getPhoneStatus(this.recoveryPhone);
  }

  get registerPhoneValid(): boolean {
    return COLOMBIAN_MOBILE_PATTERN.test(this.registerPhone);
  }

  get recoveryPhoneValid(): boolean {
    return COLOMBIAN_MOBILE_PATTERN.test(this.recoveryPhone);
  }

  updateConfirmPassword(value: string): void {
    this.confirmPassword = value;
  }

  get passwordsMatch(): boolean {
    return this.confirmPassword.length > 0 && this.registerPassword === this.confirmPassword;
  }

  get confirmationStatus(): 'mismatch' | 'valid' | '' {
    if (!this.confirmPassword) {
      return '';
    }

    return this.passwordsMatch ? 'valid' : 'mismatch';
  }

  get confirmationPattern(): string {
    return this.registerPassword.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  get passwordStrength(): PasswordStrength {
    const password = this.registerPassword;
    const criteria = [
      /[A-Z]/.test(password),
      /[a-z]/.test(password),
      /\d/.test(password),
      /[^A-Za-z0-9]/.test(password),
    ].filter(Boolean).length;

    if (criteria >= 4) {
      return 'strong';
    }

    return criteria >= 2 ? 'medium' : 'low';
  }

  get passwordStrengthLabel(): string {
    return {
      low: 'Bajo',
      medium: 'Medio',
      strong: 'Muy fuerte',
    }[this.passwordStrength];
  }

  submitLogin(event: SubmitEvent): void {
    event.preventDefault();
    if (!EMAIL_PATTERN.test(this.loginEmail.trim()) || !this.loginPassword) {
      this.loginError = 'Ingresa un correo y una contraseÃ±a válidos.';
      return;
    }

    const validCredentials =
      this.loginEmail.trim().toLowerCase() === 'jhonlopez@gmail.com' && this.loginPassword === 'Prueba123*';
    if (!validCredentials) {
      this.loginError = 'Correo o contraseÃ±a incorrectos.';
      return;
    }

    this.loginError = '';
    this.isAuthenticated = true;
  }

  submitRecovery(event: SubmitEvent): void {
    event.preventDefault();
    const emailValid = this.recoveryMethod === 'email' && EMAIL_PATTERN.test(this.recoveryEmail.trim());
    const phoneValid = this.recoveryMethod === 'sms' && this.recoveryPhoneValid;
    if (!emailValid && !phoneValid) {
      this.recoveryError =
        this.recoveryMethod === 'email' ? 'Ingresa un correo válido.' : 'Ingresa un nÃºmero de celular válido.';
      return;
    }

    this.recoveryError = '';
    this.view = 'login';
  }

  submitRegister(event: SubmitEvent): void {
    event.preventDefault();
    const nameValid = this.registerName.trim().length >= 2;
    const emailValid = EMAIL_PATTERN.test(this.registerEmail.trim());
    const passwordValid = PASSWORD_PATTERN.test(this.registerPassword);
    if (
      !nameValid ||
      !emailValid ||
      !this.registerPhoneValid ||
      !passwordValid ||
      !this.passwordsMatch ||
      !this.termsAccepted
    ) {
      this.registerError = 'Completa todos los campos correctamente para continuar.';
      return;
    }

    this.registerError = '';
    this.view = 'login';
  }
