import { Injectable } from '@angular/core';
import { Camera, CameraDirection, CameraResultType, CameraSource } from '@capacitor/camera';

const FOTO_PERFIL_KEY = 'fotoPerfilUrl';
const FOTOS_PERFIL_KEY = 'fotosPerfil';
const MAX_FOTOS_PERFIL = 6;

@Injectable({
  providedIn: 'root',
})
export class PhotoService {
  fotoPerfilUrl = localStorage.getItem(FOTO_PERFIL_KEY) ?? '';
  fotosPerfil = this.cargarFotos();

  async seleccionarFoto(source: CameraSource = CameraSource.Prompt): Promise<string | null> {
    const foto = await Camera.getPhoto({
      resultType: CameraResultType.DataUrl,
      source,
      direction: source === CameraSource.Camera ? CameraDirection.Front : undefined,
      quality: 90,
    });

    if (!foto.dataUrl) {
      return null;
    }

    return foto.dataUrl;
  }

  async guardarFoto(dataUrl: string, offsetX = 0, offsetY = 0, zoom = 1, fotoAEditar?: string): Promise<string> {
    const fotoRecortada = await this.recortarFoto(dataUrl, offsetX, offsetY, zoom);
    if (fotoAEditar) {
      this.fotosPerfil = this.fotosPerfil.map((foto) => (foto === fotoAEditar ? fotoRecortada : foto));
    } else {
      this.fotosPerfil = [fotoRecortada, ...this.fotosPerfil.filter((foto) => foto !== fotoRecortada)].slice(
        0,
        MAX_FOTOS_PERFIL,
      );
    }
    localStorage.setItem(FOTOS_PERFIL_KEY, JSON.stringify(this.fotosPerfil));
    if (this.fotoPerfilUrl === fotoAEditar || !this.fotoPerfilUrl) {
      localStorage.setItem(FOTO_PERFIL_KEY, fotoRecortada);
      this.fotoPerfilUrl = fotoRecortada;
    }
    return fotoRecortada;
  }

  establecerFotoPrincipal(foto: string): void {
    if (!this.fotosPerfil.includes(foto)) {
      return;
    }

    localStorage.setItem(FOTO_PERFIL_KEY, foto);
    this.fotoPerfilUrl = foto;
  }

  eliminarFoto(foto: string): string {
    this.fotosPerfil = this.fotosPerfil.filter((fotoGuardada) => fotoGuardada !== foto);
    localStorage.setItem(FOTOS_PERFIL_KEY, JSON.stringify(this.fotosPerfil));

    if (this.fotoPerfilUrl === foto) {
      this.fotoPerfilUrl = this.fotosPerfil[0] ?? '';
      localStorage.setItem(FOTO_PERFIL_KEY, this.fotoPerfilUrl);
    }

    return this.fotoPerfilUrl;
  }

  private cargarFotos(): string[] {
    const fotosGuardadas = localStorage.getItem(FOTOS_PERFIL_KEY);
    if (fotosGuardadas) {
      try {
        const fotos = JSON.parse(fotosGuardadas) as unknown;
        if (Array.isArray(fotos) && fotos.every((foto): foto is string => typeof foto === 'string')) {
          return fotos.slice(0, MAX_FOTOS_PERFIL);
        }
      } catch {
        localStorage.removeItem(FOTOS_PERFIL_KEY);
      }
    }

    return this.fotoPerfilUrl ? [this.fotoPerfilUrl] : [];
  }

  private recortarFoto(dataUrl: string, offsetX: number, offsetY: number, zoom: number): Promise<string> {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => {
        const canvas = document.createElement('canvas');
        const size = 512;
        const scale = Math.max(size / image.width, size / image.height) * zoom;
        const width = image.width * scale;
        const height = image.height * scale;
        const context = canvas.getContext('2d');

        if (!context) {
          reject(new Error('No se pudo preparar el recorte de la foto.'));
          return;
        }

        canvas.width = size;
        canvas.height = size;
        context.drawImage(image, (size - width) / 2 + offsetX, (size - height) / 2 + offsetY, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.9));
      };
      image.onerror = () => reject(new Error('No se pudo cargar la foto seleccionada.'));
      image.src = dataUrl;
    });
  }
}
